function NumberField({label,value,onChange,min,max,step=1,disabled=false}:{label:string;value:number;onChange:(v:number)=>void;min?:number;max?:number;step?:number;disabled?:boolean}){const [draft,setDraft]=useState(String(value));useEffect(()=>setDraft(String(value)),[value]);return <label>{label}<input type="number" value={draft} min={min} max={max} step={step} disabled={disabled} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur();}} onBlur={()=>{const n=Number(draft);if(draft!==''&&Number.isFinite(n)&&n!==value)onChange(n);else setDraft(String(value));}}/></label>;}
