 useEffect(()=>{const p=player.current;if(!p||!project)return;const onFrame=(e:{detail:{frame:number}})=>{setFrame(e.detail.frame);if(!editing){const starts=sceneStarts(project);const index=starts.findLastIndex(v=>v<=e.detail.frame);if(index>=0){const active=project.scenes[index];setSceneId(active.sceneId);setLayerId(old=>active.layers.some(l=>l.layerId===old)?old:active.layers[0]?.layerId??'');}}};const onPlay=()=>{playingRef.current=true;setPlaying(true);};const onPause=()=>{playingRef.current=false;setPlaying(false);};p.addEventListener('frameupdate',onFrame);p.addEventListener('play',onPlay);p.addEventListener('pause',onPause);return()=>{p.removeEventListener('frameupdate',onFrame);p.removeEventListener('play',onPlay);p.removeEventListener('pause',onPause);};},[project,editing]);
