 function requestPreview(mode:'scene'|'all'='scene'){const p=projectRef.current;if(!p)return;const index=p.scenes.findIndex(s=>s.sceneId===sceneId),start=mode==='all'?0:sceneStarts(p)[Math.max(0,index)];previewRequest.current={start};setEditing(false);setTrialBefore(false);setLoopScene(mode==='scene');setFrame(start);setPreviewTicket(v=>v+1);}
