 async function saveForHandoff(){if(saving)throw Error('保存中です。完了後に実行してください');if(trial)throw Error('試着を先に採用または取消してください');const snapshot=clone(projectRef.current!);setSaving(true);try{if(snapshot.revision!==savedRevision){await api('/api/projects/'+snapshot.projectId,'PUT',{project:snapshot,baseRevision:savedRevision});setSavedRevision(snapshot.revision);}const source=await api('/api/projects/'+snapshot.projectId);if(stable(source)!==stable(snapshot)||stable(projectRef.current)!==stable(snapshot))throw Error('保存中に編集や別の保存がありました。最新状態からやり直してください');return source as Project;}finally{setSaving(false);}}
 async function acceptHandoffSaved(next:Project,source:Project,description:string){let current=projectRef.current!;if(current.projectId!==next.projectId){setMessage('別作品の保存が完了しました。切替先は変更しません');return;}setSavedRevision(next.revision);setHistory(await api('/api/projects/'+next.projectId+'/history'));current=projectRef.current!;if(current.projectId!==next.projectId)return;setPast(v=>[...v.slice(-79),clone(current)]);setFuture([]);if(stable(current)===stable(source)){setProject(next);setMessage(description+'（保存済み）');}else{const merged=clone(current),local=ensureState(merged),remote=stateOf(next);local.checkpoints=[...new Map([...local.checkpoints,...remote.checkpoints].map(c=>[c.id,c])).values()];local.records=[...new Map([...local.records,...remote.records].map(r=>[r.id,r])).values()];local.baselineId??=remote.baselineId;local.activeHandoffId=remote.activeHandoffId;merged.revision=Math.max(current.revision,next.revision)+1;setProject(merged);setMessage(description+'。生成中の追加編集は保持しています（未保存）');}}
