 function undo(redo=false){if(!project)return;const from=redo?future:past;if(!from.length)return;const snapshot=clone(from.at(-1)!);snapshot.revision=project.revision+1;if(redo){setFuture(from.slice(0,-1));setPast(v=>[...v,clone(project)]);}else{setPast(from.slice(0,-1));setFuture(v=>[...v,clone(project)]);}setProject(snapshot);setMessage(redo?'やり直しました（未保存）':'元に戻しました（未保存）');}
