 const scene=project.scenes.find(s=>s.sceneId===sceneId)??project.scenes[0],layer=scene.layers.find(l=>l.layerId===layerId)??scene.layers[0],length=totalFrames(project),starts=sceneStarts(project),sceneIndex=project.scenes.indexOf(scene);
