 function duration(seconds:number){if(!Number.isFinite(seconds)||seconds<=0||seconds>600){setMessage('秒数は0秒より大きく600秒以内にしてください');return;}const frames=Math.round(seconds*project!.video.fps);if(project!.video.durationPolicy==='fixed'){try{if(protectedPath(project!,'scene',scene.sceneId,'durationFrames',true))throw Error('尺が固定されています');const next=redistribution(project!,scene.sceneId,frames);setPending({project:next,base:project!.revision,description:next.scenes.map((s,i)=>`${names[s.role]??s.sceneId}: ${project!.scenes[i].durationFrames/project!.video.fps} → ${s.durationFrames/project!.video.fps}秒`).join('\n')});}catch(e){fail(e);}}else sceneEdit('durationFrames',s=>{s.durationFrames=frames;});}
 function lock(scope:'scene'|'layer',target:string,field:string){const next=clone(project!);const index=next.locks.findIndex(l=>l.scope===scope&&l.targetId===target&&l.field===field);if(index>=0)next.locks.splice(index,1);else{if(scope==='scene'&&field==='colorOverrides'){const s=next.scenes.find(s=>s.sceneId===target)!;s.colorOverrides={...next.theme.palette,...s.colorOverrides};}next.locks.push({scope,targetId:target,field});}commit(next,index>=0?'固定を解除':'固定しました');}
