 function duplicateScene(){const next=clone(project!);if(next.scenes.length>=80){setMessage('コマ数の上限は80です');return;}const copy=clone(scene),map=new Map<string,string>();copy.sceneId=id('sc');copy.layers.forEach(l=>{const old=l.layerId;l.layerId=id('ly');map.set(old,l.layerId);});copy.unplacedLayerIds=copy.unplacedLayerIds.map(v=>map.get(v)!);remapSceneAnimations(copy,map);next.scenes.splice(sceneIndex+1,0,copy);commit(next,'コマを複製');setSceneId(copy.sceneId);setLayerId(copy.layers[0]?.layerId??'');}
 async function createProject(){try{if(project!.revision!==savedRevision){setMessage('新規作成の前に現在の編集を保存してください');return;}const p=await api('/api/example');p.projectId=id('project');p.title='新しい動画プロジェクト';p.revision=1;await api(`/api/projects/${p.projectId}`,'PUT',{project:p,baseRevision:null});setProjects(await api('/api/projects'));await load(p.projectId);}catch(e){fail(e);}}
