 async function upload(files:FileList|null){if(!files)return;const snapshot=projectRef.current!;try{const next=clone(snapshot);for(const file of Array.from(files)){if(file.size>20*1024*1024)throw Error('素材は20MB以内にしてください');const kind=file.type.startsWith('video/')?'video':file.type.startsWith('image/')?'image':'audio',thumb=kind==='audio'?null:await mediaThumbnail(file,kind);const r=await fetch('/api/projects/'+snapshot.projectId+'/assets',{method:'POST',headers:{'X-Promo-Local':'1','Content-Type':file.type||'application/octet-stream'},body:file});const data=await r.json();if(!r.ok)throw Error(data.error);if(thumb){const t=await fetch('/api/projects/'+snapshot.projectId+'/assets/'+data.assetId+'/thumbnail',{method:'POST',headers:{'X-Promo-Local':'1','Content-Type':'image/jpeg'},body:thumb.thumbnail});const info=await t.json();if(!t.ok)throw Error(info.error);Object.assign(data,{posterPath:info.posterPath,width:thumb.width,height:thumb.height,...(thumb.durationSeconds!==undefined?{durationSeconds:thumb.durationSeconds}:{})});}next.assets.push({...data,originalName:file.name.slice(0,255)});}if(projectRef.current?.projectId!==snapshot.projectId||projectRef.current.revision!==snapshot.revision)throw Error('アップロード中に編集が進みました。再度アップロードしてください');markManual(next,'project',next.projectId,'assets');commit(next,'素材を追加');}catch(e){fail(e);}}
 function tryAnimation(a:Animation){try{if(protectedPath(project!,'scene',scene.sceneId,'*',true)||protectedPath(project!,a.targetScope==='scene'?'scene':'layer',a.targetLayerId??scene.sceneId,'animations',true))throw Error('対象が固定されています');const next=clone(trial?.animation&&trial.base===project!.revision?trial.project:project!),s=next.scenes.find(v=>v.sceneId===scene.sceneId)!;const owner=a.targetScope==='scene'?s:s.layers.find(v=>v.layerId===a.targetLayerId);if(!owner)throw Error('対象がありません');
 // An existing preset may change scope between the scene and its selected layer.
 if(s.animations?.some(v=>v.id===a.id))s.animations=s.animations.filter(v=>v.id!==a.id);for(const l of s.layers)if(l.animations?.some(v=>v.id===a.id))l.animations=l.animations.filter(v=>v.id!==a.id);owner.animations=[...(owner.animations??[]),clone(a)];markManual(next,a.targetScope==='scene'?'scene':'layer',a.targetLayerId??scene.sceneId,'animations');validateProject(next);setTrial({project:next,base:project!.revision,sceneId:scene.sceneId,label:a.presetId+' / '+(a.targetLayerId??'コマ全体')+' / '+(a.targetScope==='imageContent'?'枠固定・内部画像':a.targetScope),animation:a});requestPreview();}catch(e){fail(e);}}
 function animationNote(value:string){if(trial){setMessage('試着を採用またはキャンセルしてからメモを保存してください');return;}const next=clone(project!),h=ensureState(next),now=new Date().toISOString();h.notes.push({id:id('note'),projectId:next.projectId,scope:layer?'layer':'scene',sceneId:scene.sceneId,...(layer?{layerId:layer.layerId}:{}),targetName:layer?.layerId??scene.sceneId,text:value,kind:'wish',status:'open',createdAt:now,updatedAt:now} as typeof h.notes[number]);commit(next,'アニメーション指定を引き継ぎメモへ保存');noteTarget({scope:layer?'layer':'scene',sceneId:scene.sceneId,...(layer?{layerId:layer.layerId}:{})});}
 function tryMotion(motionId:string){try{const next=clone(trial?.project??project!),target=next.scenes.find(s=>s.sceneId===scene.sceneId)!;if(protectedPath(project!,'scene',scene.sceneId,'*',true))throw Error('コマの固定を解除してください');const m={motionId,startOffsetFrames:0,durationFrames:Math.min(scene.durationFrames,project!.video.fps*2),params:{speed:1}};if(motionTarget==='scene'){if(protectedPath(project!,'scene',scene.sceneId,'motionStack',true))throw Error('動きの固定を解除してください');target.motionStack=[m];markManual(next,'scene',scene.sceneId,'motionStack');}else{const l=target.layers.find(l=>l.layerId===layer?.layerId);if(!l||target.unplacedLayerIds.includes(l.layerId)||!l.visible)throw Error('表示中のレイヤーを選択してください');if(protectedPath(project!,'layer',l.layerId,'motionStack',true))throw Error('レイヤーの固定を解除してください');l.motionStack=[m];markManual(next,'layer',l.layerId,'motionStack');}setTrial({project:next,base:project!.revision,sceneId:scene.sceneId,label:(target.layout.presetId??'現在の構成')+' + '+motionId+' / '+(motionTarget==='scene'?'コマ全体':'選択レイヤー')});setCatalogOpen(false);requestPreview();}catch(e){fail(e);}}
